// The lab pages' data (src/labs/<course>/, generated by tools/labs_build.ts
// from docs/lessons/<course>/labs): for every course, both languages, every
// code block of the Markdown, the code files, none of the text lost,
// everything renderable by the text-page reader; and the generated files are
// up to date.
/// <reference types="vite/client" />
import { describe, expect, it } from 'vitest';
import { tr, type Block, type Lang } from '@mathnim/core';
import { labs_of, load_lab, type LabMeta, type LabModule } from '../src/labs';
// ('.js' finds labs_build.ts; without an extension the .mjs launcher would be picked)
import { LAB_COURSES, build_sources, labs_index_source } from '../tools/labs_build.js';
import { blocks_html } from '../../../packages/present/src/text_pages';

// the sources and the generated modules of every course, read through Vite (path -> contents)
const DOC_MDS = import.meta.glob('../../../docs/lessons/*/labs/*.md', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;
const DOC_CODE = import.meta.glob('../../../docs/lessons/*/labs/code/*', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;
const GENERATED_ALL = import.meta.glob(['../src/labs/**/*.ts', '!../src/labs/types.ts'], { query: '?raw', import: 'default', eager: true }) as Record<string, string>;
const INDEXES = import.meta.glob('../src/labs/*/index.ts', { eager: true }) as Record<string, { LABS: LabMeta[]; lab_meta: (slug: string) => LabMeta | undefined }>;
/** The files of one folder, by file name. */
const in_dir = (files: Record<string, string>, dir: string): Record<string, string> =>
  Object.fromEntries(Object.entries(files).filter(([p]) => p.slice(0, p.lastIndexOf('/')).endsWith(dir)).map(([p, s]) => [p.split('/').pop()!, s]));
const LANGS: Lang[] = ['zh', 'en'];
// every course's labs, loaded
const LOADED: Record<string, LabModule[]> = Object.fromEntries(
  await Promise.all(LAB_COURSES.map(async (c) => [c.course, await Promise.all(labs_of(c.course).map((m) => load_lab(c.course, m.slug)))] as const)),
);

/** The Markdown of a lab: the preamble and each language section (without the "---" before the next one). */
function sections(md: string): { pre: string; zh: string; en: string } {
  const lines = md.replace(/\r\n?/g, '\n').split('\n');
  const at = (h: string) => lines.findIndex((l) => l.trim() === h);
  const zh = at('## 中文');
  const en = at('## English');
  expect(zh).toBeGreaterThan(0);
  expect(en).toBeGreaterThan(zh);
  return {
    pre: lines.slice(1, zh).join('\n'),
    zh: lines.slice(zh + 1, en).join('\n').replace(/\n---\s*$/, ''),
    en: lines.slice(en + 1).join('\n'),
  };
}

/** The contents of the fenced code blocks of some Markdown (indented fences inside list items included, dedented). */
function fenced(md: string): string[] {
  const out: string[] = [];
  let open: { indent: number; lines: string[] } | null = null;
  for (const line of md.split('\n')) {
    const m = /^(\s*)```/.exec(line);
    if (m && !open) open = { indent: m[1].length, lines: [] };
    else if (m && open) {
      out.push(open.lines.join('\n'));
      open = null;
    } else if (open) open.lines.push(line.slice(Math.min(open.indent, /^\s*/.exec(line)![0].length)));
  }
  expect(open).toBeNull();
  return out;
}

/** Every block, depth first (details included). */
const all = (bs: Block[]): Block[] => bs.flatMap((b) => (b.type === 'details' ? [b, ...all(b.blocks)] : [b]));

/** Markdown text with its markup taken out: what is left must be the same words in the same order. */
function md_words(md: string): string {
  let inside = false;
  const kept = md.split('\n').flatMap((line) => {
    if (/^\s*```/.test(line)) {
      inside = !inside;
      return [];
    }
    if (inside) return [line];
    if (/^\s*(---+|\|?[\s:|-]+\|?)\s*$/.test(line) && line.includes('-')) return []; // rules, table separator rows
    return [line.replace(/^\s*(?:[-*+]|\d+\.)\s+/, '').replace(/^\s*#+\s+/, '')];
  });
  return squash(kept.join('\n'));
}
/** The same for blocks: every text and code, in order. */
function block_words(bs: Block[]): string {
  const parts: string[] = [];
  for (const b of bs) {
    switch (b.type) {
      case 'h': case 'p': parts.push(b.text as string); break;
      case 'list': parts.push(...(b.items as string[])); break;
      case 'code': parts.push(b.code); break;
      case 'table': parts.push(...(b.head as string[]), ...b.rows.flat().map(String)); break;
      case 'callout': parts.push(String(b.title ?? ''), b.body as string); break;
      case 'details': parts.push(b.summary as string, block_words(b.blocks)); break;
      case 'cite': parts.push(`[^${b.key}]:`, b.text as string, b.url); break;
      case 'math': parts.push(`$$${b.tex}$$`); break;
      default: parts.push(JSON.stringify(b));
    }
  }
  return squash(parts.join('\n'));
}
const squash = (s: string) => s.replace(/[\s*`#|>\\]/g, '');

it('src/labs/index.ts gives every course its labs (npm run labs -w mathnim)', async () => {
  expect(GENERATED_ALL['../src/labs/index.ts']).toBe(labs_index_source());
  expect(labs_of('nope')).toEqual([]);
  await expect(load_lab('nope', 'l1-x')).rejects.toThrow(/no labs/);
});

for (const course of LAB_COURSES) describe(`labs of ${course.course}`, () => {
  const MDS = in_dir(DOC_MDS, course.docs);
  const CODE = in_dir(DOC_CODE, `${course.docs}/code`);
  const GENERATED = in_dir(GENERATED_ALL, `src/labs/${course.dir}`);
  const MD_FILES = Object.keys(MDS).filter((f) => /^L\d+-.+\.md$/.test(f)).sort();
  const { LABS, lab_meta } = INDEXES[`../src/labs/${course.dir}/index.ts`];
  const labs = LOADED[course.course];

  it('lists one lab per tutorial, in order, with card data in both languages', () => {
    expect(labs_of(course.course)).toBe(LABS);
    expect(LABS.map((l) => `${l.slug}.md`)).toEqual(MD_FILES.map((f) => f.toLowerCase()));
    for (const m of LABS) {
      expect(m.id).toMatch(/^L\d+$/);
      for (const lang of LANGS) {
        expect(m.title[lang].trim(), `${m.id} title ${lang}`).not.toBe('');
        expect(m.summary[lang].trim(), `${m.id} summary ${lang}`).not.toBe('');
        expect(tr(m.configs_summary, lang).trim(), `${m.id} configs_summary ${lang}`).not.toBe('');
        for (const c of m.configs) for (const k of ['label', 'gpu', 'note'] as const) expect(tr(c[k], lang).trim(), `${m.id} config ${k} ${lang}`).not.toBe('');
      }
      // two or three setups, exactly one recommended; no prices (nothing has been measured)
      expect(m.configs.length).toBeGreaterThanOrEqual(2);
      expect(m.configs.length).toBeLessThanOrEqual(3);
      expect(m.configs.filter((c) => c.recommended)).toHaveLength(1);
      expect(JSON.stringify(m.configs) + JSON.stringify(m.configs_summary)).not.toMatch(/[$¥€]|USD|美元|元\/|分钟|minutes?\b/);
      expect(lab_meta(m.slug)).toBe(m);
    }
    expect(lab_meta('nope')).toBeUndefined();
  });

  it('loads every lab, and refuses an unknown slug', async () => {
    labs.forEach((lab, i) => {
      const { blocks: _b, files: _f, list_starts: _s, ...meta } = lab;
      expect(meta).toEqual(LABS[i]);
    });
    await expect(load_lab(course.course, 'l9-nothing')).rejects.toThrow(/unknown lab/);
  });

  for (const [i, file] of MD_FILES.entries()) {
    describe(file, () => {
      const md = MDS[file];
      const sec = sections(md);
      const lab = () => labs[i];

      it('has both languages, each with a non-empty block list that opens with the status warning', () => {
        for (const lang of LANGS) {
          const bs = lab().blocks[lang];
          expect(bs.length, lang).toBeGreaterThan(5);
          const first = bs[0];
          expect(first.type).toBe('callout');
          if (first.type !== 'callout') return;
          expect(first.kind).toBe('warning');
          if (course.not_run) expect(first.body).toContain(course.not_run[lang]);
          // the banner is the preamble's paragraph of that language, word for word
          const para = sec.pre.split('\n').filter((l) => l.startsWith('> ') && /[㐀-鿿]/.test(l) === (lang === 'zh')).join(' ').slice(2);
          expect(squash(`${first.title}${first.body}`)).toBe(squash(para).replace(/[：:]/, ''));
        }
      });

      it('keeps every fenced code block of each language, in order and unchanged', () => {
        for (const lang of LANGS) {
          const want = fenced(sec[lang]);
          const got = all(lab().blocks[lang]).flatMap((b) => (b.type === 'code' ? [b.code] : []));
          expect(got.length, `${lang}: ${want.length} fenced blocks in the Markdown`).toBe(want.length);
          expect(got).toEqual(want);
        }
      });

      it('keeps all the text of each section (only the Markdown markup differs)', () => {
        for (const lang of LANGS) expect(block_words(lab().blocks[lang].slice(1)), lang).toBe(md_words(sec[lang]));
      });

      it('carries the code files the tutorial lists, as they are on disk', () => {
        const files = lab().files;
        expect(files.length).toBeGreaterThan(0);
        expect(files[0].name).toMatch(new RegExp(`^${lab().id}_\\w+\\.py$`));
        // every lab says what to install; the fine-tuning labs share common.py
        expect(files.map((f) => f.name)).toEqual(expect.arrayContaining(course.dir === 'ft' ? ['common.py', 'requirements.txt'] : ['requirements.txt']));
        for (const f of files) {
          expect(f.code).toBe(CODE[f.name]);
          expect(f.lang).toBe(f.name.endsWith('.py') ? 'python' : 'text');
          // the setup section names it in both languages
          for (const lang of LANGS) expect(sec[lang]).toContain(`\`${f.name}\``);
        }
      });

      it('renders with the text-page reader: footnotes resolve, every code block shows, no markup is left over', () => {
        for (const lang of LANGS) {
          const bs = lab().blocks[lang];
          const html = blocks_html(bs, lang);
          expect(html).not.toContain('mn-fnref-missing');
          expect(html.match(/class="mn-codeblock"/g)?.length ?? 0).toBe(all(bs).filter((b) => b.type === 'code').length);
          const text = html.replace(/<pre[\s\S]*?<\/pre>/g, '').replace(/<code>[\s\S]*?<\/code>/g, '');
          expect(text, `${lang}: unrendered ** / * / \``).not.toMatch(/[*`]/);
          // math is rendered; the only dollars left are the literal ones (\$ in the Markdown, outside code)
          const literal = (sec[lang].replace(/^\s*```[\s\S]*?^\s*```/gm, '').replace(/`[^`\n]*`/g, '').match(/\\\$/g) ?? []).length;
          expect((text.match(/\$/g) ?? []).length, `${lang}: unrendered $`).toBe(literal);
          // numbered lists that continue after a code block say where they go on
          const ordered = all(bs).filter((b) => b.type === 'list' && b.ordered).length;
          const starts = lab().list_starts?.[lang];
          if (starts) expect(starts.length).toBe(ordered);
        }
      });
    });
  }

  it('the generated files are up to date (npm run labs -w mathnim)', () => {
    const sources = build_sources(course, { mds: MDS, code: CODE });
    expect(Object.keys(GENERATED).sort()).toEqual(Object.keys(sources).sort());
    for (const [f, src] of Object.entries(sources)) expect(GENERATED[f], f).toBe(src);
  });
});
